using UnityEngine;
namespace CoopBeam {
public class LinkPickup:MonoBehaviour {
 public enum Kind{Prism,Shield,Heart,Chain,Solar} public Kind kind;public LinkPowers owner;
 public float Age{get;private set;}public bool Collected{get;private set;}public bool Ready=>Age>=1.2f;
 float life=18;Vector3 origin,anchor;SpriteRenderer art,halo;
 static int nextLabelId;int labelId;void Awake(){labelId=++nextLabelId;} static int labelFrame=-1;static readonly System.Collections.Generic.Dictionary<int,Rect> labelRects=new System.Collections.Generic.Dictionary<int,Rect>();
 public static string Label(Kind kind)=>kind==Kind.Prism?"PRISMA / +DANO":kind==Kind.Shield?"BURBUJA / ESCUDO":kind==Kind.Heart?"CORAZON / VIDA":kind==Kind.Chain?"CHISPA / CADENA":"ANILLO / PULSOS";
 public static Color ColorFor(Kind kind)=>kind==Kind.Prism?Color.cyan:kind==Kind.Shield?new Color(.7f,.5f,1):kind==Kind.Heart?new Color(1,.4f,.6f):kind==Kind.Chain?new Color(1,.7f,.12f):new Color(1,.35f,.12f);
 public static LinkPickup Create(Vector3 position,Kind kind){if(FindObjectsByType<LinkPickup>().Length>0)return null;var g=new GameObject("Visible loot - "+kind);g.transform.position=new Vector3(Mathf.Clamp(position.x,-9.5f,9.5f),Mathf.Clamp(position.y,-3.6f,3.3f),0);var pickup=g.AddComponent<LinkPickup>();pickup.kind=kind;return pickup;}
 void Start(){origin=transform.position;anchor=origin+Vector3.up*1.05f;art=gameObject.AddComponent<SpriteRenderer>();art.sprite=ExpansionSprites.Icon((int)kind);art.sortingOrder=15;transform.localScale=Vector3.one*.9f;var g=new GameObject("Loot beacon");g.transform.SetParent(transform,false);g.transform.localScale=Vector3.one*1.35f;halo=g.AddComponent<SpriteRenderer>();halo.sprite=ExpansionSprites.Icon(4);halo.color=new Color(ColorFor(kind).r,ColorFor(kind).g,ColorFor(kind).b,.35f);halo.sortingOrder=14;FireFX.Burst(origin,ColorFor(kind),10);}
 public bool TryCollect(){if(Collected||!Ready||!owner||owner.ActiveBonus||!GameManager.Instance||!GameManager.Instance.Running)return false;var director=owner.GetComponent<CoopInteractionDirector>();if(director&&director.HasPending)return false;if(director){var players=GameManager.Instance.players;director.Collector=Vector2.Distance(players[0].transform.position,transform.position)<=Vector2.Distance(players[1].transform.position,transform.position)?0:1;}Collected=true;GameDuoAudio.PlayPowerup();owner.Collect(kind);FireFX.Burst(transform.position,ColorFor(kind),18);Destroy(gameObject);return true;}
 void Update(){var game=GameManager.Instance;if(!owner||!game||!game.Running){Destroy(gameObject);return;}Age+=Time.deltaTime;life-=Time.deltaTime;if(life<=0){Destroy(gameObject);return;}transform.position=Vector3.Lerp(origin,anchor,Mathf.SmoothStep(0,1,Age/1.2f))+Vector3.up*Mathf.Sin(Age*4)*.12f;transform.localScale=Vector3.one*(.9f+Mathf.Sin(Age*5)*.06f);if(halo)halo.transform.localRotation=Quaternion.Euler(0,0,Age*75);art.color=life<3&&Mathf.Sin(Age*20)>0?new Color(1,1,1,.3f):Color.white;if(!Ready)return;foreach(var h in game.players)if(!h.Dead&&Vector2.Distance(h.transform.position,transform.position)<.85f){TryCollect();return;}if(!game.players[0].Dead&&!game.players[1].Dead&&LinkPowers.Distance(transform.position,game.players[0].transform.position,game.players[1].transform.position)<.36f)TryCollect();}
 static void LayoutLabels(Camera camera){if(labelFrame==Time.frameCount)return;labelFrame=Time.frameCount;labelRects.Clear();var pickups=FindObjectsByType<LinkPickup>();System.Array.Sort(pickups,(a,b)=>a.labelId.CompareTo(b.labelId));var placed=new System.Collections.Generic.List<Rect>();foreach(var item in pickups){if(item.Collected||!item.owner)continue;var view=camera.WorldToViewportPoint(item.transform.position);if(view.z<0)continue;float width=Label(item.kind).Length*6+12;var basis=new Rect(Mathf.Clamp(view.x*640-width/2,4,636-width),Mathf.Clamp((1-view.y)*360-27,78,318),width,17);var result=basis;for(int trial=0;trial<25;trial++){int step=trial==0?0:(trial+1)/2*(trial%2==1?-1:1);var candidate=basis;candidate.y+=step*19;if(candidate.y<78||candidate.y>318)continue;bool overlaps=false;foreach(var old in placed)if(candidate.Overlaps(old)){overlaps=true;break;}if(!overlaps){result=candidate;break;}}placed.Add(result);labelRects[item.labelId]=result;}}
 void OnGUI(){if(Collected||!owner||!GameManager.Instance||!GameManager.Instance.Running||!Camera.main)return;LayoutLabels(Camera.main);if(!labelRects.TryGetValue(labelId,out var rect))return;GUI.depth=-2;PixelFont.Begin();PixelFont.Panel(rect,PixelFont.Ink,ColorFor(kind));PixelFont.Text(rect.x+6,rect.y+5,Label(kind),1,Color.white);}
}
public static class ExpansionSprites {
 static Sprite square,shard,column,snowball;static Sprite[] icons=new Sprite[5];
 public static Sprite Hazard(bool projectile,bool round){var illustrated=IllustratedWorldLibrary.Sprite(1,round?25:projectile?26:21);if(illustrated)return illustrated;if(round&&snowball)return snowball;if(!round&&projectile&&shard)return shard;if(!projectile&&column)return column;var t=new Texture2D(32,32,TextureFormat.RGBA32,false){filterMode=FilterMode.Point};for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Abs(x-15.5f),dy=Mathf.Abs(y-15.5f);bool inside=round?dx*dx+dy*dy<210:projectile?dx<8*(1-dy/16):y<23?x>2&&x<29:dx<Mathf.Max(0,(32-y)*1.7f);bool ridge=(x+y)%13<2;Color c=inside?(ridge?new Color(.55f,.7f,1):x<13?Color.white:new Color(.72f,.87f,1)):Color.clear;t.SetPixel(x,y,c);}t.Apply();var s=Sprite.Create(t,new Rect(0,0,32,32),Vector2.one*.5f,32);if(round)snowball=s;else if(projectile)shard=s;else column=s;return s;}
 public static Sprite Square {get{if(!square){var t=new Texture2D(1,1);t.SetPixel(0,0,Color.white);t.Apply();square=Sprite.Create(t,new Rect(0,0,1,1),Vector2.one*.5f,1);}return square;}}
 public static Sprite Icon(int kind){var illustrated=IllustratedWorldLibrary.Sprite(kind==0?1:0,kind==2?28:kind==1?25:kind==0?21:27);if(illustrated)return illustrated;kind=Mathf.Clamp(kind,0,4);if(icons[kind])return icons[kind];var t=new Texture2D(16,16,TextureFormat.RGBA32,false){filterMode=FilterMode.Point};for(int y=0;y<16;y++)for(int x=0;x<16;x++){float dx=Mathf.Abs(x-7.5f),dy=Mathf.Abs(y-7.5f),r=dx*dx+dy*dy;bool heart=(y>6&&((x>2&&x<8)||(x>7&&x<13))&&y<12)||(y<=6&&dx<y+.5f);bool bolt=(y>7&&x>5&&x<11)||(y<=8&&x>=4&&x<9)||(y==8&&x>=3&&x<13);bool sun=r>14&&r<42||((x==7||x==8)&&dy>6)||((y==7||y==8)&&dx>6);bool inside=kind==0?dx+dy<7:kind==1?r<44:kind==2?heart:kind==3?bolt:sun;var c=LinkPickup.ColorFor((LinkPickup.Kind)kind);t.SetPixel(x,y,inside?(x<6&&y>8?Color.white:c):Color.clear);}t.Apply();return icons[kind]=Sprite.Create(t,new Rect(0,0,16,16),Vector2.one*.5f,16);}
}
}
